function ClientForm({data,close,save}){const [f,setF]=useState({...data});const s=(k,v)=>setF(x=>({...x,[k]:v}));return <ModalShell title={data.id?'Uredi klijenta':'Novi klijent'} sub="Kontaktni i poslovni podaci klijenta." close={close} wide><form onSubmit={e=>{e.preventDefault();save(f)}}><div className="form-grid"><Field label="Vrsta klijenta"><Select value={f.type} onChange={v=>s('type',v)}><option>Fizičko lice</option><option>Pravno lice</option></Select></Field><Field label="Naziv / ime klijenta"><Input value={f.name} onChange={v=>s('name',v)} placeholder="npr. Kovač d.o.o." required/></Field><Field label="Kontakt osoba"><Input value={f.contact} onChange={v=>s('contact',v)} placeholder="Ime i prezime" required/></Field><Field label="Status"><Select value={f.status} onChange={v=>s('status',v)}><option>Aktivan</option><option>Novi upit</option><option>Neaktivan</option></Select></Field><Field label="Email"><Input type="email" value={f.email} onChange={v=>s('email',v)} placeholder="kontakt@firma.ba"/></Field><Field label="Telefon"><Input value={f.phone} onChange={v=>s('phone',v)} placeholder="+387 6X XXX XXX"/></Field><Field label="Poštanski broj"><Input value={f.postal_code} onChange={v=>s('postal_code',v)} placeholder="75001"/></Field><Field label="Grad"><Input value={f.city} onChange={v=>s('city',v)} placeholder="Paris"/></Field><Field label="Adresa"><Input value={f.address} onChange={v=>s('address',v)} placeholder="Ulica i broj"/></Field><Field label="Država" hint="Koristi se za ispravan obračun PDV-a na računima i ponudama."><Select value={f.country||''} onChange={v=>s('country',v)}><option value="">Nepoznato / ostalo</option><option value="France">Francuska</option><option value="Belgium">Belgija</option><option value="Luxembourg">Luksemburg</option></Select></Field><div className="full client-locations-editor"><div className="line-items-head"><strong>Dodatne servisne lokacije</strong><button type="button" onClick={()=>s('locations',[...(Array.isArray(f.locations)?f.locations:[]),''])}><Plus/> Dodaj lokaciju</button></div>{(Array.isArray(f.locations)?f.locations:[]).map((a,i)=><div className="line-item" key={i}><input value={typeof a==='string'?a:a.address||''} onChange={e=>s('locations',f.locations.map((x,j)=>j===i?e.target.value:x))} placeholder="Puna adresa servisne lokacije"/><button type="button" onClick={()=>s('locations',f.locations.filter((_,j)=>j!==i))}><X/></button></div>)}</div><Field label="Interna bilješka" full><textarea value={f.note||''} onChange={e=>s('note',e.target.value)} placeholder="Važne informacije o klijentu..."/></Field></div><ModalActions close={close}><button className="primary"><Check/> Sačuvaj klijenta</button></ModalActions></form></ModalShell>}

