 const [search,setSearch]=useRouteState('q',''),[status,setStatus]=useRouteState('status','Svi statusi'),[modal,setModal]=useState(null),[selected,setSelected]=useState(null),[notice,setNotice]=useState(null),[events,setEvents]=useState([]);
 useEffect(()=>{if(!openIntent)return;if(openIntent.filter==='open')setStatus('Otvoreni poslovi');if(openIntent.filter==='unassigned')setStatus('Otvoreni bez radnika');if(openIntent.filter==='create')setModal({type:'form',data:{status:'Novi',priority:'Standardno',date:new Date().toLocaleDateString('bs-BA'),time:'08:00'}});if(openIntent.filter==='create-client')setModal({type:'form',data:{status:'Novi',priority:'Standardno',date:new Date().toLocaleDateString('bs-BA'),time:'08:00',client:openIntent.data?.client,client_id:openIntent.data?.clientId,city:openIntent.data?.locations?.length===1?openIntent.data.locations[0]:'',client_locations:openIntent.data?.locations||[]}});const found=items.find(x=>String(x.id)===String(openIntent.id));if(found)setSelected(found);onIntentHandled?.()},[openIntent?.nonce,items]);
 const isOpen=x=>!['Završeno','Otkazano'].includes(x.status),isUnassigned=x=>isOpen(x)&&!String(x.worker||'').trim();
 const filtered=items.filter(x=>`${x.no} ${x.client} ${x.service} ${x.worker}`.toLowerCase().includes(search.toLowerCase())&&(status==='Svi statusi'||(status==='Otvoreni poslovi'?isOpen(x):status==='Otvoreni bez radnika'?isUnassigned(x):status==='Završeni ovog mjeseca'?(x.status==='Završeno'&&dateInCurrentMonth(x.completed_at||x.date)):x.status===status)));
