 const save=async f=>{const editing=!!f.id,payload={...f};delete payload.id;delete payload.created_at;delete payload.company_id;const saved=editing?await updateJob(f.id,payload):await createJob(payload);if(!saved?.id)throw new Error('Posao nije sačuvan jer server nije vratio identifikator zapisa.');setModal(null);const hidden=status!=='Svi statusi'&&(status==='Otvoreni poslovi'?!isOpen(saved):status==='Otvoreni bez radnika'?!isUnassigned(saved):status==='Završeni ovog mjeseca'?!((saved.status==='Završeno')&&dateInCurrentMonth(saved.completed_at||saved.date)):saved.status!==status)||!!search&&!`${saved.no} ${saved.client} ${saved.service} ${saved.worker}`.toLowerCase().includes(search.toLowerCase());setNotice({message:`Posao ${saved.no||`#${saved.id}`} je sačuvan.`,job:saved,hidden});return saved};
 useEffect(()=>{if(!selected){setEvents([]);return}fetch(`/api/jobs/${selected.id}/events`,{credentials:'include'}).then(r=>r.ok?r.json():[]).then(d=>setEvents(Array.isArray(d)?d:[])).catch(()=>setEvents([]))},[selected?.id,selected?.status]);
 const workerRole=role==='Radnik na terenu';
