export function MaintenanceModule({openIntent,onIntentHandled}){
 const {maintenance:items,setMaintenance:setItems,saveMaintenance,clients,workers,loading,error,reload}=useData();
 const [search,setSearch]=useRouteState('q',''),[worker,setWorker]=useRouteState('worker','Svi radnici'),[deadlineFilter,setDeadlineFilter]=useState('all'),[modal,setModal]=useState(null);
 useEffect(()=>{if(!openIntent)return;const found=items.find(x=>String(x.id)===String(openIntent.id));if(found)setModal({type:'form',data:found});onIntentHandled?.()},[openIntent?.nonce,items]);
 const today=new Date();today.setHours(0,0,0,0);const dueInfo=x=>{const d=parseEUFull(x.next);d.setHours(0,0,0,0);const days=Math.round((d-today)/86400000);return{date:d,days,label:days<0?`Kasni ${Math.abs(days)} ${Math.abs(days)===1?'dan':'dana'}`:days===0?'Danas':`Za ${days} dana`}};
 const isActive=x=>!/neaktivan|otkazan|završen/i.test(x.status||'');
 const overdue=items.filter(x=>isActive(x)&&dueInfo(x).days<0),upcoming=items.filter(x=>isActive(x)&&dueInfo(x).days>=0&&dueInfo(x).days<=30);
 const filtered=items.filter(x=>`${x.client} ${x.asset} ${x.service}`.toLowerCase().includes(search.toLowerCase())&&(worker==='Svi radnici'||x.worker===worker)&&(deadlineFilter==='all'||(deadlineFilter==='overdue'?isActive(x)&&dueInfo(x).days<0:isActive(x)&&dueInfo(x).days>=0&&dueInfo(x).days<=30))).sort((a,b)=>dueInfo(a).days-dueInfo(b).days);
 const openNew=()=>setModal({type:'form',data:{next:formatEUFull(addDays(today,30)),cycle:'12 mjeseci',status:'Aktivan'}}),clearFilters=()=>{setSearch('');setWorker('Svi radnici');setDeadlineFilter('all')};
 const save=async f=>{const saved=await saveMaintenance({...f,status:f.status||'Aktivan',first_service_date:f.first_service_date||f.next,next:f.first_service_date||f.next},f.id||null);setModal(null);return saved};
 const completedThisYear=items.filter(x=>dateInCurrentYear(x.completed_at||x.last_service)&&/obavljen|završen/i.test(x.status||'')).length;
 const exportList=()=>exportToPDF('Održavanje',`Pregled servisnih planova — ${filtered.length} od ${items.length} zapisa`,['Klijent','Oprema','Servis','Sljedeći termin','Rok','Ciklus','Radnik','Status'],filtered.map(x=>[x.client,x.asset,x.service,formatEUFull(dueInfo(x).date),dueInfo(x).label,x.cycle,x.worker,x.status]));
 return <><Header eyebrow="PONAVLJAJUĆI POSLOVI" title="Održavanje" description="Servisni planovi, rokovi i automatski podsjetnici." button="Novi plan" onAdd={openNew}/><div className="module-metrics four"><Metric icon={RefreshCw} label="Aktivni planovi" value={items.filter(isActive).length} sub="Trenutno aktivni" onClick={()=>setDeadlineFilter('all')} active={deadlineFilter==='all'}/><Metric icon={AlertTriangle} label="Servisi koji kasne" value={overdue.length} sub="Rok je istekao" tone="red" onClick={()=>setDeadlineFilter('overdue')} active={deadlineFilter==='overdue'}/><Metric icon={Clock3} label="U narednih 30 dana" value={upcoming.length} sub="Danas i predstojeći termini" tone="orange" onClick={()=>setDeadlineFilter('upcoming')} active={deadlineFilter==='upcoming'}/><Metric icon={CheckCircle2} label="Obavljeni servisi ove godine" value={completedThisYear} sub="Prema evidenciji završetka" tone="green"/></div><section className="card"><Toolbar search={search} setSearch={setSearch} placeholder="Klijent, uređaj ili servis..." statusOptions={['Svi radnici',...workers.map(w=>w.name)]} statusValue={worker} setStatusValue={setWorker} filterLabel="Radnik" onExport={exportList}/>{deadlineFilter!=='all'&&<div className="active-filter-summary"><span>Rok: <strong>{deadlineFilter==='overdue'?'Servisi koji kasne':'U narednih 30 dana'}</strong></span><button type="button" onClick={()=>setDeadlineFilter('all')}><X/> Očisti filter rokova</button></div>}<div className="table-wrap maintenance-table-wrap"><table className="maintenance-table"><thead><tr><th>Klijent</th><th>Oprema / lokacija</th><th>Vrsta servisa</th><th>Sljedeći termin</th><th>Ciklus</th><th>Radnik</th><th>Status plana</th><th>Akcije</th></tr></thead><tbody>{filtered.map(x=>{const due=dueInfo(x);return <tr key={x.id}><td><strong>{x.client}</strong></td><td>{x.asset}<small className="table-sub maintenance-address">{x.service_address||'Adresa servisa nije unesena'}</small></td><td>{x.service}</td><td><strong>{formatEUFull(due.date)}</strong><small className={`table-sub maintenance-due ${due.days<0?'overdue':due.days===0?'today':'upcoming'}`}>{due.label}</small></td><td>{x.cycle}</td><td>{x.worker}</td><td><Badge>{x.status||'Aktivan'}</Badge></td><td><Actions onView={()=>setModal({type:'view',data:x})} onEdit={()=>setModal({type:'form',data:x})} onDelete={()=>setModal({type:'delete',data:x})}/></td></tr>})}</tbody></table>{!loading&&error?<div className="jobs-empty-state"><AlertTriangle/><strong>Servisne planove nije moguće učitati</strong><button className="secondary" onClick={()=>reload().catch(()=>{})}><RefreshCw/> Pokušaj ponovo</button></div>:!loading&&!items.length?<div className="jobs-empty-state"><Wrench/><strong>Još nemate servisnih planova</strong><button className="primary" onClick={openNew}><Plus/> Kreiraj prvi servisni plan</button></div>:!loading&&!filtered.length?<div className="jobs-empty-state"><Search/><strong>Nema servisnih planova za odabrane filtere</strong><button className="secondary" onClick={clearFilters}><X/> Očisti filtere</button></div>:null}</div></section>{modal?.type==='view'&&<MaintenancePlanView data={modal.data} close={()=>setModal(null)}/>} {modal?.type==='form'&&<MaintenanceForm data={modal.data} clients={clients} workers={workers} close={()=>setModal(null)} save={save}/>} {modal?.type==='delete'&&<ConfirmDelete name={`${modal.data.client} · ${modal.data.asset}`} onClose={()=>setModal(null)} onConfirm={()=>{setItems(a=>a.filter(x=>x.id!==modal.data.id));setModal(null)}}/>}</>}
function MaintenancePlanView({data,close}){const rows=[['Klijent',data.client],['Uređaj',data.asset],['Lokacija servisa',data.service_address||'—'],['Vrsta servisa',data.service],['Sljedeći termin',String(data.next||data.first_service_date||'—').replace(/\.$/,'')],['Ponavljanje',data.cycle],['Odgovorni radnik',data.worker],['Status plana',data.status||'Aktivan']];return <ModalShell title="Pregled servisnog plana" sub="Podaci odabranog plana samo za čitanje." close={close}><div className="maintenance-plan-view">{rows.map(([label,value])=><div key={label}><span>{label}</span><strong>{value||'—'}</strong></div>)}</div><div className="modal-actions"><button type="button" className="primary" onClick={close}>Zatvori</button></div></ModalShell>}
function MaintenanceForm({data,close,save,workers=[],clients=[]}){const [f,setF]=useState(()=>({...data,first_service_date:data.first_service_date||data.next||'',service_address:data.service_address||''})),[error,setError]=useState(''),[busy,setBusy]=useState(false);const selected=clients.find(c=>c.name===f.client),baseAddress=selected?[selected.address,[selected.postal_code,selected.city].filter(Boolean).join(' ')].filter(Boolean).join(', '):'',savedLocations=selected?[...new Set([baseAddress,...(Array.isArray(selected.locations)?selected.locations.map(x=>typeof x==='string'?x:[x.address,[x.postal_code,x.city].filter(Boolean).join(' ')].filter(Boolean).join(', ')):[])].filter(Boolean))]:[];const s=(k,v)=>{setF(x=>({...x,[k]:v}));setError('')},pickClient=v=>{const c=clients.find(x=>x.name===v),address=c?[c.address,[c.postal_code,c.city].filter(Boolean).join(' ')].filter(Boolean).join(', '):'';setF(x=>({...x,client:v,service_address:address}));setError('')};const months=parseInt(f.cycle)||0,first=parseEUFull(f.first_service_date),repeat=f.first_service_date&&months?new Date(first.getFullYear(),first.getMonth()+months,first.getDate()):null;const submit=async e=>{e.preventDefault();if(!f.client||!f.asset||!f.service||!f.service_address||!f.first_service_date||!f.cycle||!f.status||!f.worker){setError('Popunite sva obavezna polja.');return}setBusy(true);try{await save({...f,next:f.first_service_date})}catch(e){setError(e.message||'Servisni plan nije sačuvan. Uneseni podaci su zadržani.')}finally{setBusy(false)}};return <ModalShell title={data.id?'Uredi servisni plan':'Novi servisni plan'} sub="Plan ostaje na prvom neobavljenom terminu dok servis ne bude evidentiran." close={close} wide><form onSubmit={submit}><div className="form-grid maintenance-plan-form"><Field label="Klijent *" full><Select value={f.client} onChange={pickClient}><option value="">Odaberite klijenta</option>{clients.map(c=><option key={c.id}>{c.name}</option>)}</Select></Field><Field label="Oprema / uređaj *"><Input value={f.asset} onChange={v=>s('asset',v)} placeholder="npr. Klima uređaj Daikin" required/></Field><Field label="Vrsta servisa *"><Input value={f.service} onChange={v=>s('service',v)} placeholder="Godišnji servis" required/></Field><Field label="Lokacija servisa *" full>{savedLocations.length>1&&<Select value={savedLocations.includes(f.service_address)?f.service_address:'manual'} onChange={v=>v!=='manual'&&s('service_address',v)}>{savedLocations.map(a=><option key={a} value={a}>{a}</option>)}<option value="manual">Druga adresa — ručni unos</option></Select>}<Input value={f.service_address} onChange={v=>s('service_address',v)} placeholder="Ulica, broj, poštanski broj i grad" required/><span className="field-help">Adresa vrijedi samo za ovaj plan i ne mijenja osnovnu adresu klijenta.</span></Field><Field label={data.id?'Sljedeći termin *':'Datum prvog servisa *'}><EUDate value={f.first_service_date} onChange={v=>s('first_service_date',v)}/></Field><Field label="Ponavljanje *"><Select value={f.cycle} onChange={v=>s('cycle',v)}><option value="">Odaberite ciklus</option><option>3 mjeseca</option><option>6 mjeseci</option><option>12 mjeseci</option><option>24 mjeseca</option></Select></Field>{f.first_service_date&&months>0&&<div className="maintenance-plan-preview full"><CalendarDays/><span>Prvi servis: <strong>{String(f.first_service_date).replace(/\.$/,'')}</strong> · Ponavlja se svaka {months} mjeseca · Naredno ponavljanje: <strong>{formatEUFull(repeat).replace(/\.$/,'')}</strong></span></div>}<Field label="Status plana *"><Select value={f.status||'Aktivan'} onChange={v=>s('status',v)}><option>Aktivan</option><option>Neaktivan</option><option>Otkazan</option></Select></Field><Field label="Odgovorni radnik *"><Select value={f.worker} onChange={v=>s('worker',v)}><option value="">Odaberite radnika</option>{f.worker&&!workers.some(w=>w.name===f.worker)&&<option>{f.worker}</option>}{workers.map(w=><option key={w.id} value={w.name}>{w.name} · {w.role}</option>)}</Select>{!workers.length&&<span className="field-help">Nema aktivnih korisnika firme.</span>}</Field>{error&&<p className="otp-error full"><AlertTriangle/> {error}</p>}</div><ModalActions close={close}><button className="primary" disabled={busy}><Check/> {busy?'Čuvanje...':'Sačuvaj plan'}</button></ModalActions></form></ModalShell>}

const DAY_START=7,DAY_END=19,SLOT_PX=60,HEAD_PX=42;
const DAY_SHORT=['PON','UTO','SRI','ČET','PET','SUB','NED'];
const MONTH_NAMES=['januar','februar','mart','april','maj','juni','juli','august','septembar','oktobar','novembar','decembar'];
const SCHEDULE_TODAY=(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate())})();
function pad2(n){return String(n).padStart(2,'0');}
function formatEUFull(d){return `${pad2(d.getDate())}.${pad2(d.getMonth()+1)}.${d.getFullYear()}.`;}
function parseEUFull(s){const m=(s||'').match(/(\d{2})\.(\d{2})\.(\d{4})/);return m?new Date(+m[3],+m[2]-1,+m[1]):new Date();}
function addDays(d,n){const r=new Date(d);r.setDate(r.getDate()+n);return r;}
function mondayOf(d){const day=(d.getDay()+6)%7;return addDays(d,-day);}
function sameDate(a,b){return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();}
function timeToMin(t){const [h,m]=(t||'08:00').split(':').map(Number);return h*60+m;}
function toneOfWorker(w,workers=[]){const i=Math.max(0,workers.findIndex(x=>x.name===w));return ['marko','ivan','petar'][i%3]||'gray';}
function weekRangeLabel(monday){const sunday=addDays(monday,6);return monday.getMonth()===sunday.getMonth()?`${monday.getDate()}. — ${sunday.getDate()}. ${MONTH_NAMES[monday.getMonth()]} ${monday.getFullYear()}.`:`${monday.getDate()}. ${MONTH_NAMES[monday.getMonth()]} — ${sunday.getDate()}. ${MONTH_NAMES[sunday.getMonth()]} ${sunday.getFullYear()}.`;}
function yToTime(relY,dayEnd=DAY_END){let minutes=DAY_START*60+Math.round(((relY-HEAD_PX)/SLOT_PX)*60/30)*30;minutes=Math.max(DAY_START*60,Math.min((dayEnd-1)*60+30,minutes));return `${pad2(Math.floor(minutes/60))}:${pad2(minutes%60)}`;}

export function ScheduleModule({openIntent,onIntentHandled}){
 const quickTerm=routeParams().get('quick')==='term';
 const {jobs,setJobs,createJob,updateJob,clients,workers}=useData();
 const workerNames=workers.map(w=>w.name);
 const [weekStart,setWeekStart]=useState(()=>{const q=routeParams().get('week');return q?mondayOf(parseEUFull(q)):mondayOf(SCHEDULE_TODAY)});
 const [monthCursor,setMonthCursor]=useState(()=>{const q=routeParams().get('month');return q?new Date(Number(q.slice(0,4)),Number(q.slice(5,7))-1,1):new Date(SCHEDULE_TODAY.getFullYear(),SCHEDULE_TODAY.getMonth(),1)});
 const [view,setView]=useRouteState('view','week');
 const [modal,setModal]=useState(null);
 const [selected,setSelected]=useState(null);
 const [workerFilter,setWorkerFilter]=useRouteState('worker','Svi radnici');
 const [statusFilter,setStatusFilter]=useRouteState('status','Svi statusi');
 const [dragOverKey,setDragOverKey]=useState('');
 const [warning,setWarning]=useState('');
 const [notice,setNotice]=useState('');
 useEffect(()=>{replaceQuery({week:view==='week'?formatEUFull(weekStart):null,month:view==='month'?`${monthCursor.getFullYear()}-${pad2(monthCursor.getMonth()+1)}`:null})},[view,weekStart,monthCursor]);
 useEffect(()=>{if(!openIntent)return;if(openIntent.filter==='today'){setWeekStart(mondayOf(SCHEDULE_TODAY));setMonthCursor(new Date(SCHEDULE_TODAY.getFullYear(),SCHEDULE_TODAY.getMonth(),1));setStatusFilter('Bez otkazanih');setView('week')}const found=jobs.find(x=>String(x.id)===String(openIntent.id));if(found){setSelected(found);const d=parseEUFull(found.date);setWeekStart(mondayOf(d));setMonthCursor(new Date(d.getFullYear(),d.getMonth(),1));setView('week')}onIntentHandled?.()},[openIntent?.nonce,jobs]);

 const flash=(msg,isWarning)=>{if(isWarning){setWarning(msg);setTimeout(()=>setWarning(''),5000);}else{setNotice(msg);setTimeout(()=>setNotice(''),3000);}};
 const filteredJobs=jobs.filter(j=>(workerFilter==='Svi radnici'||j.worker===workerFilter)&&(statusFilter==='Svi statusi'||(statusFilter==='Bez otkazanih'?j.status!=='Otkazano':j.status===statusFilter)));
 const weekDays=Array.from({length:7},(_,i)=>addDays(weekStart,i));
 const latestHour=Math.max(DAY_END,...filteredJobs.map(j=>Math.floor(timeToMin(j.time)/60)+1)),gridEnd=Math.min(24,latestHour);
 const hours=Array.from({length:gridEnd-DAY_START},(_,i)=>`${pad2(DAY_START+i)}:00`);

 const checkOverlap=(job,excludeId)=>jobs.find(x=>x.id!==excludeId&&x.worker===job.worker&&x.date===job.date&&Math.abs(timeToMin(x.time)-timeToMin(job.time))<90);
 const isPastSlot=(date,time='00:00')=>{const d=parseEUFull(date);const chosen=new Date(d.getFullYear(),d.getMonth(),d.getDate(),Math.floor(timeToMin(time)/60),timeToMin(time)%60);return chosen<new Date()};
 const openNewSlot=(day,time='08:00')=>{
  const date=formatEUFull(day);
  if(isPastSlot(date,time)){flash('Nije moguće zakazati termin u prošlosti.',true);return;}
  setModal({type:'form',data:{status:'Zakazano',priority:'Standardno',date,time,worker:workerFilter!=='Svi radnici'?workerFilter:''}});
 };

 const saveJob=async f=>{
  if(isPastSlot(f.date,f.time)){const msg='Termin mora biti u budućnosti. Odaberite današnji kasniji termin ili naredni datum.';flash(msg,true);throw new Error(msg);}
  if(!f.client||!f.service||!f.worker){const msg='Odaberite klijenta i radnika te unesite vrstu usluge.';flash(msg,true);throw new Error(msg);}
  const overlap=checkOverlap(f,f.id);
  if(overlap){const msg=`${f.worker} već ima termin ${overlap.time} (${overlap.client}). Odaberite drugi termin.`;flash(msg,true);throw new Error(msg);}
  let saved;
  try{saved=f.id?await updateJob(f.id,f):await createJob(f);}
  catch(e){const msg=e.message||'Termin nije sačuvan na serveru. Pokušajte ponovo.';flash(msg,true);throw new Error(msg);}
  if(!saved?.id){const msg='Server nije potvrdio čuvanje termina.';flash(msg,true);throw new Error(msg);}
  setModal(null);
  flash(`Termin za ${saved.client||'klijenta'} je sačuvan.`);
  return saved;
 };
 const deleteJob=async job=>{try{await setJobs(a=>a.filter(x=>x.id!==job.id));setModal(null);setSelected(null);flash('Termin je obrisan.');}catch(e){flash(e.message||'Termin nije obrisan na serveru.',true);}};
 const reassignWorker=async(job,worker)=>{
  const updated={...job,worker};
  const overlap=checkOverlap(updated,job.id);
  try{
   const saved=await updateJob(job.id,updated);
   setSelected(saved);
   flash(overlap?`Upozorenje: ${worker} već ima termin u to vrijeme.`:`Radnik promijenjen na ${worker}.`,!!overlap);
  }catch(e){flash(e.message||'Radnik nije promijenjen na serveru.',true);}
 };
 const setJobStatus=async(job,status)=>{try{const saved=await updateJob(job.id,{...job,status});setSelected(saved);flash(`Status ažuriran na "${status}".`);}catch(e){flash(e.message||'Status nije ažuriran na serveru.',true);}};

 const handleDrop=async(e,day)=>{
  e.preventDefault();setDragOverKey('');
  const id=Number(e.dataTransfer.getData('text/plain'));
  const job=jobs.find(x=>x.id===id);if(!job)return;
  const rect=e.currentTarget.getBoundingClientRect();
  const newTime=yToTime(e.clientY-rect.top,gridEnd);
  const updated={...job,date:formatEUFull(day),time:newTime};
  if(isPastSlot(updated.date,updated.time)){flash('Termin nije moguće premjestiti u prošlost.',true);return;}
  const overlap=checkOverlap(updated,job.id);
  if(overlap){flash(`${job.worker} već ima termin ${overlap.time} (${overlap.client}). Premještanje nije izvršeno.`,true);return;}
  try{await updateJob(id,updated);flash(`Termin premješten na ${updated.date} u ${newTime}.`);}
  catch(e){flash(e.message||'Termin nije premješten na serveru.',true);}
 };
 const dayClick=(e,day)=>{
  if(e.target.closest('.schedule-job'))return;
  const rect=e.currentTarget.getBoundingClientRect();
  openNewSlot(day,yToTime(e.clientY-rect.top,gridEnd));
 };

 const monthStart=new Date(monthCursor.getFullYear(),monthCursor.getMonth(),1);
 const monthEnd=new Date(monthCursor.getFullYear(),monthCursor.getMonth()+1,0);
 const gridStart=mondayOf(monthStart);
 const gridEndMonday=mondayOf(monthEnd);
 const totalDays=Math.round((addDays(gridEndMonday,6)-gridStart)/86400000)+1;
 const monthCells=Array.from({length:totalDays},(_,i)=>addDays(gridStart,i));

 const exportWeek=()=>exportToPDF('Raspored',`Sedmica: ${weekRangeLabel(weekStart)}`,['Datum','Vrijeme','Klijent','Usluga','Radnik','Status'],weekDays.flatMap(d=>filteredJobs.filter(j=>j.date===formatEUFull(d)).map(j=>[j.date,j.time,j.client,j.service,j.worker,j.status])));

 return <><Header eyebrow="PLANIRANJE EKIPE" title="Raspored" description="Sedmični i mjesečni pregled termina i dostupnosti radnika. Kliknite na slobodan termin ili datum za dodavanje zadatka." button="Novi termin" onAdd={()=>openNewSlot(SCHEDULE_TODAY,`${pad2(Math.max(DAY_START,new Date().getHours()+1))}:00`)}/>
 <div className="report-filter schedule-filter-row">
  <div><label>Radnik</label><div className="select-icon report-select"><UserRound/><Select value={workerFilter} onChange={setWorkerFilter}>{['Svi radnici',...workerNames].map(w=><option key={w}>{w}</option>)}</Select></div></div>
  <div><label>Status</label><div className="select-icon report-select"><Filter/><Select value={statusFilter} onChange={setStatusFilter}>{['Svi statusi','Bez otkazanih','Novi','Zakazano','U toku','Završeno'].map(s=><option key={s}>{s}</option>)}</Select></div></div>
  {(workerFilter!=='Svi radnici'||statusFilter!=='Svi statusi')&&<button type="button" className="text-link" onClick={()=>{setWorkerFilter('Svi radnici');setStatusFilter('Svi statusi');}}>Poništi filtere</button>}
  <button type="button" className="secondary export-btn" onClick={exportWeek}><Download/> Izvezi PDF</button>
 </div>
 {warning&&<div className="schedule-warning"><AlertTriangle/> {warning}</div>}
 {notice&&<div className="settings-inline-notice"><CheckCircle2/> {notice}</div>}
 <section className="card schedule-pro">
  <div className="schedule-nav">
   <div><button type="button" className="secondary" onClick={()=>view==='week'?setWeekStart(d=>addDays(d,-7)):setMonthCursor(d=>new Date(d.getFullYear(),d.getMonth()-1,1))}><ChevronLeft/></button><button type="button" className="secondary today-btn" onClick={()=>{setWeekStart(mondayOf(SCHEDULE_TODAY));setMonthCursor(new Date(SCHEDULE_TODAY.getFullYear(),SCHEDULE_TODAY.getMonth(),1));}}>Danas</button><button type="button" className="secondary" onClick={()=>view==='week'?setWeekStart(d=>addDays(d,7)):setMonthCursor(d=>new Date(d.getFullYear(),d.getMonth()+1,1))}><ChevronRight/></button></div>
   <strong>{view==='week'?weekRangeLabel(weekStart):`${MONTH_NAMES[monthCursor.getMonth()][0].toUpperCase()}${MONTH_NAMES[monthCursor.getMonth()].slice(1)} ${monthCursor.getFullYear()}.`}</strong>
   <div className="segmented"><button type="button" className={view==='week'?'active':''} onClick={()=>setView('week')}>Sedmica</button><button type="button" className={view==='month'?'active':''} onClick={()=>{setMonthCursor(new Date(weekStart.getFullYear(),weekStart.getMonth(),1));setView('month');}}>Mjesec</button></div>
  </div>
  <div className="worker-legend">{workers.map(w=><span key={w.id}><i className={toneOfWorker(w.name,workers)}></i>{w.name}</span>)}{!workers.length&&<span>Nema aktivnih korisnika firme</span>}</div>
  {view==='week'?
  <div className="pro-week days7" style={{minHeight:HEAD_PX+hours.length*SLOT_PX}}>
   <div className="pro-hours"><strong>Vrijeme</strong>{hours.map(t=><span key={t}>{t}</span>)}</div>
   {weekDays.map((d,i)=>{
    const key=formatEUFull(d);
    const dayJobs=filteredJobs.filter(j=>j.date===key);
    const isToday=sameDate(d,SCHEDULE_TODAY);
    const isWeekend=i===6;
    return <div key={key} className={`pro-day ${isToday?'today':''} ${isWeekend?'nonworking':''} ${dragOverKey===key?'drag-over':''}`}
     onDragOver={e=>{e.preventDefault();setDragOverKey(key);}} onDragLeave={()=>setDragOverKey(k=>k===key?'':k)} onDrop={e=>handleDrop(e,d)}
     onClick={e=>dayClick(e,d)}>
     <strong>{DAY_SHORT[i]} {d.getDate()}</strong>
     {isWeekend&&<span className="nonworking-flag">Neradni dan</span>}
     {dayJobs.map(j=><button key={j.id} type="button" draggable className={`schedule-job ${toneOfWorker(j.worker,workers)}`}
       style={{top:HEAD_PX+((timeToMin(j.time)-DAY_START*60)/60)*SLOT_PX,height:80}}
       onDragStart={e=>e.dataTransfer.setData('text/plain',String(j.id))}
       onDoubleClick={e=>e.stopPropagation()}
       onClick={e=>{e.stopPropagation();setSelected(j);}}>
       <strong>{j.client}</strong><span>{j.service}</span><small><Clock3/>{j.time} · {j.worker.split(' ')[0]}</small>
      </button>)}
    </div>;
   })}
  </div>
  :
  <>
   <div className="month-weekdays">{DAY_SHORT.map(x=><span key={x}>{x}</span>)}</div>
   <div className="month-grid">{monthCells.map((d,i)=>{
    const dayJobs=filteredJobs.filter(j=>parseEUFull(j.date).getTime()===new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime());
    const otherMonth=d.getMonth()!==monthCursor.getMonth();
    const isToday=sameDate(d,SCHEDULE_TODAY);
    const past=new Date(d.getFullYear(),d.getMonth(),d.getDate())<SCHEDULE_TODAY;
    const visible=dayJobs.slice(0,3),extra=dayJobs.length-visible.length;
    return <div key={i} className={`month-cell ${otherMonth?'otherMonth':''} ${isToday?'today':''} ${past?'past-day':''}`} role="button" tabIndex={past?-1:0} title={past?'Nije moguće zakazati termin u prošlosti':'Kliknite za novi termin'} onClick={e=>{if(e.target.closest('.m-job-line')||past)return;openNewSlot(d,'08:00')}} onKeyDown={e=>{if(!past&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openNewSlot(d,'08:00')}}}>
     <strong>{d.getDate()}</strong>
     {dayJobs.length>0&&<div className="m-jobs">{visible.map(j=><button type="button" key={j.id} className={`m-job-line ${toneOfWorker(j.worker,workers)}`} onClick={e=>{e.stopPropagation();setSelected(j)}}><i className="m-dot"/><span className="m-job-time">{j.time}</span><span className="m-job-text">{j.client} · {j.service}</span></button>)}{extra>0&&<span className="m-more">+{extra} više</span>}</div>}
    </div>;
   })}</div>
  </>}
 </section>
 {modal?.type==='form'&&<JobForm data={modal.data} workers={workers} close={()=>setModal(null)} save={saveJob}/>}
 {modal?.type==='delete'&&<ConfirmDelete name={`${modal.data.no||''} ${modal.data.client}`} onClose={()=>setModal(null)} onConfirm={()=>deleteJob(modal.data)}/>}
 {selected&&<DetailDrawer title={selected.client} sub={`${selected.service} · ${selected.date} u ${selected.time}`} close={()=>setSelected(null)} actions={<><button className="secondary" onClick={()=>setModal({type:'delete',data:selected})}><Trash2/> Obriši</button><button className="secondary" onClick={()=>setModal({type:'form',data:selected})}><Edit3/> Uredi termin</button>{selected.status!=='Završeno'&&<button className="primary" onClick={()=>setJobStatus(selected,selected.status==='U toku'?'Završeno':'U toku')}><CheckCircle2/> {selected.status==='U toku'?'Završi posao':'Označi u toku'}</button>}</>}>
  <div className="job-status-hero"><Badge>{selected.status}</Badge><span className={`priority ${selected.priority?.toLowerCase()}`}>{selected.priority}</span></div>
  <InfoGrid items={[["Klijent",selected.client],["Usluga",selected.service],["Datum",selected.date],["Vrijeme",selected.time],["Adresa intervencije",selected.service_address||selected.city],["Vrijednost",selected.amount]]}/>
  <div className="drawer-section"><h4>Promijeni radnika</h4><Select value={selected.worker} onChange={v=>reassignWorker(selected,v)}>{workerNames.map(w=><option key={w}>{w}</option>)}</Select></div>
 </DetailDrawer>}
 </>;
}

