  {step==='loading'&&<div className="twofa-body"><p>{error||'Generisanje sigurnog QR koda...'}</p></div>}
  {step==='qr'&&<div className="twofa-body"><h3>Skenirajte QR kod</h3><p>Otvorite autentikator aplikaciju i skenirajte ovaj jedinstveni kod.</p><div className="qr-wrap"><img src={qr} alt="2FA QR kod" style={{width:210,height:210}}/></div><div className="secret-key"><span>Ključ za ručni unos</span><code>{secret}</code><button type="button" onClick={()=>navigator.clipboard?.writeText(secret)}><Copy/></button></div><ModalActions close={close}><button className="primary" onClick={()=>setStep('verify')}>Nastavi <ArrowRight/></button></ModalActions></div>}
